scripts.script:
task.spawn(function()
    local ok1, err1 = pcall(function()
        loadstring(game:HttpGet(
            "https://raw.githubusercontent.com/akiru-hub/Gaming-Focused-V0.02/main/Gaming%20Focused%20fixed%20universal%200.02.txt"
        ))()
    end)

    if not ok1 then
        warn("Main script failed:", err1)
    end

    task.delay(2, function()
        local ok2, err2 = pcall(function()
            loadstring(game:HttpGet(
                "https://raw.githubusercontent.com/akiru-hub/Gaming-Focused-V0.02-fixed-/main/Gaming%20Focused%200.33%20%28fixed%29%20music%20player.txt"
            ))()
        end)

        if not ok2 then
            warn("Music player failed:", err2)
        end
    end)
end)
